PROCEDURE CREATE_VIRTUAL() IS
BEGIN
CREATE TABLE
SYS_VIRTUAL(TABLE_ID BIGINT,POS INT,BASE_POS INT);
CREATE UNIQUE CLUSTERED INDEX BASE_IDX ON SYS_VIRTUAL(TABLE_ID, POS, BASE_POS);
END;

